// Client is a unified client for every service of this API, all sharing the
// same address and HTTP client: c.Users.Get(ctx, …). Skip it when services
// need different transports (e.g. separate admin vs user credentials) — the
// per-service constructors stay.
type Client struct {
	TestApi     TestApiClient
	TestApiRest TestApiRestClient
}

func NewClient(addr string, client HTTPClient) *Client {
	return &Client{
		TestApi:     NewTestApiClient(addr, client),
		TestApiRest: NewTestApiRestClient(addr, client),
	}
}

//
// Server
//

type WebRPCServer interface {
	http.Handler
}

type Options struct {
	OnError   func(r *http.Request, rpcErr *WebRPCError)
	OnRequest func(w http.ResponseWriter, r *http.Request) error
	// MaxUploadSize caps multipart/form-data request bodies of file upload
	// methods. Defaults to DefaultMaxUploadSize when zero.
	MaxUploadSize int64
}

type testApiService struct {
	TestApiServer
	OnError       func(r *http.Request, rpcErr *WebRPCError)
	OnRequest     func(w http.ResponseWriter, r *http.Request) error
	MaxUploadSize int64
}

func NewTestApiServer(svc TestApiServer, options ...*Options) *testApiService {
	server := &testApiService{
		TestApiServer: svc,
	}
	if len(options) > 0 && options[0] != nil {
		server.OnError = options[0].OnError
		server.OnRequest = options[0].OnRequest
		server.MaxUploadSize = options[0].MaxUploadSize
	}
	return server
}

func (s *testApiService) Methods() []Method { return methodsFor(ServiceTestApi, s) }

func (s *testApiService) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	defer func() {
		// In case of a panic, serve a HTTP 500 error and then panic.
		if rr := recover(); rr != nil {
			s.sendErrorJSON(w, r, ErrWebrpcServerPanic.WithCausef("%v", rr))
			panic(rr)
		}
	}()

	w.Header().Set(WebrpcHeader, WebrpcHeaderValue)

	ctx := r.Context()
	ctx = context.WithValue(ctx, HTTPResponseWriterCtxKey, w)
	ctx = context.WithValue(ctx, HTTPRequestCtxKey, r)
	ctx = context.WithValue(ctx, ServiceNameCtxKey, "TestApi")

	r = r.WithContext(ctx)

	var handler func(ctx context.Context, w http.ResponseWriter, r *http.Request)
	expectedContentType := "application/json"
	switch r.URL.Path {
	case "/rpc/TestApi/GetEmpty":
		handler = s.serveGetEmptyJSON
	case "/rpc/TestApi/GetError":
		handler = s.serveGetErrorJSON
	case "/rpc/TestApi/GetOne":
		handler = s.serveGetOneJSON
	case "/rpc/TestApi/SendOne":
		handler = s.serveSendOneJSON
	case "/rpc/TestApi/GetMulti":
		handler = s.serveGetMultiJSON
	case "/rpc/TestApi/SendMulti":
		handler = s.serveSendMultiJSON
	case "/rpc/TestApi/GetComplex":
		handler = s.serveGetComplexJSON
	case "/rpc/TestApi/SendComplex":
		handler = s.serveSendComplexJSON
	case "/rpc/TestApi/GetEnumList":
		handler = s.serveGetEnumListJSON
	case "/rpc/TestApi/GetEnumMap":
		handler = s.serveGetEnumMapJSON
	case "/rpc/TestApi/GetSchemaError":
		handler = s.serveGetSchemaErrorJSON
	case "/rpc/TestApi/UploadFile":
		handler = s.serveUploadFileMultipart
		expectedContentType = "multipart/form-data"
	case "/rpc/TestApi/UploadFiles":
		handler = s.serveUploadFilesMultipart
		expectedContentType = "multipart/form-data"
	case "/rpc/TestApi/DownloadFile":
		handler = s.serveDownloadFileJSON
	case "/rpc/TestApi/EchoFile":
		handler = s.serveEchoFileMultipart
		expectedContentType = "multipart/form-data"
	default:
		err := ErrWebrpcBadRoute.WithCausef("no webrpc method defined for path %v", r.URL.Path)
		s.sendErrorJSON(w, r, err)
		return
	}

	if r.Method != "POST" {
		w.Header().Add("Allow", "POST") // RFC 9110.
		err := ErrWebrpcBadMethod.WithCausef("unsupported HTTP method %v (only POST is allowed)", r.Method)
		s.sendErrorJSON(w, r, err)
		return
	}

	contentType := r.Header.Get("Content-Type")
	if i := strings.Index(contentType, ";"); i >= 0 {
		contentType = contentType[:i]
	}
	contentType = strings.TrimSpace(strings.ToLower(contentType))

	switch contentType {
	case expectedContentType:
		if s.OnRequest != nil {
			if err := s.OnRequest(w, r); err != nil {
				var rpcErr WebRPCError
				if !errors.As(err, &rpcErr) {
					rpcErr = ErrWebrpcEndpoint.WithCause(err)
				}
				s.sendErrorJSON(w, r, rpcErr)
				return
			}
		}

		handler(ctx, w, r)
	default:
		err := ErrWebrpcBadRequest.WithCausef("unsupported Content-Type %q (only %s is allowed)", r.Header.Get("Content-Type"), expectedContentType)
		s.sendErrorJSON(w, r, err)
	}
}

