func (s *testApiRestService) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	defer func() {
		// In case of a panic, serve a HTTP 500 error and then panic.
		if rr := recover(); rr != nil {
			s.sendErrorJSON(w, r, ErrWebrpcServerPanic.WithCausef("%v", rr))
			panic(rr)
		}
	}()

	w.Header().Set(WebrpcHeader, WebrpcHeaderValue)

	// One canonical escaped path for the whole dispatch: static cases and
	// segment matchers compare it, so %2F stays inside one segment and
	// percent-encoded segments still match, like http.ServeMux.
	path := restEscapedPath(r.URL)

	// Method-first dispatch: one switch per verb, then static paths, then
	// segment matchers. Handlers are fully self-contained (context preamble
	// included), so this function allocates nothing on the hot path.
	switch r.Method {
	case "GET", "HEAD":
		switch path {
		case "/rpc/items":
			s.restListItems(w, r)
		case "/rpc/items/echo/params":
			s.restEchoParams(w, r)
		case "/rpc/items/find":
			s.restFindItems(w, r)
		default:
			if restTail, ok := strings.CutSuffix(path, "/status/latest"); ok {
				if id, ok := restSeg1(restTail, "/rpc/items/"); ok {
					r.SetPathValue("id", id)
					s.restGetItemStatus(w, r)
					return
				}
			}
			if id, childId, ok := restSeg2(path, "/rpc/items/", "/children/"); ok {
				r.SetPathValue("id", id)
				r.SetPathValue("childId", childId)
				s.restGetChild(w, r)
				return
			}
			if id, ok := restSeg1(path, "/rpc/items/lookup/"); ok {
				r.SetPathValue("id", id)
				s.restLookupItem(w, r)
				return
			}
			if id, ok := restSeg1(path, "/rpc/items/"); ok {
				r.SetPathValue("id", id)
				s.restGetItem(w, r)
				return
			}
			s.restMiss(w, r)
		}
	case "POST":
		switch path {
		case "/rpc/items":
			s.restCreateItem(w, r)
		case "/rpc/items/purge":
			s.restPurgeItems(w, r)
		case "/rpc/items/reset":
			s.restResetItems(w, r)
		case "/rpc/TestApiRest/LookupItem":
			s.restLookupItemRPC(w, r)
		case "/rpc/TestApiRest/RpcMethod":
			s.handleRpcMethod(w, r)
		default:
			s.restMiss(w, r)
		}
	case "PUT":
		switch path {
		case "/rpc/items":
			s.restUpsertItem(w, r)
		default:
			if id, ok := restSeg1(path, "/rpc/items/"); ok {
				r.SetPathValue("id", id)
				s.restUpdateItem(w, r)
				return
			}
			s.restMiss(w, r)
		}
	case "PATCH":
		if id, ok := restSeg1(path, "/rpc/items/"); ok {
			r.SetPathValue("id", id)
			s.restPatchItem(w, r)
			return
		}
		s.restMiss(w, r)
	case "DELETE":
		if id, ok := restSeg1(path, "/rpc/items/"); ok {
			r.SetPathValue("id", id)
			s.restDeleteItem(w, r)
			return
		}
		s.restMiss(w, r)
	case "QUERY":
		switch path {
		case "/rpc/items/search":
			s.restQueryItems(w, r)
		case "/rpc/items/find":
			s.restFindItemsQuery(w, r)
		default:
			s.restMiss(w, r)
		}
	default:
		s.restMiss(w, r)
	}
}

// handleRpcMethod serves the plain RPC method, self-contained so it works
// both in ServeHTTP's dispatch and when mounted on an external mux.
func (s *testApiRestService) handleRpcMethod(w http.ResponseWriter, r *http.Request) {
	r.Pattern = "/rpc/TestApiRest/RpcMethod" // MethodCtx resolves the method by this key.
	ctx := r.Context()
	ctx = context.WithValue(ctx, HTTPResponseWriterCtxKey, w)
	ctx = context.WithValue(ctx, HTTPRequestCtxKey, r)
	ctx = context.WithValue(ctx, ServiceNameCtxKey, "TestApiRest")

	r = r.WithContext(ctx)

	if r.Method != "POST" {
		w.Header().Add("Allow", "POST") // RFC 9110.
		err := ErrWebrpcBadMethod.WithCausef("unsupported HTTP method %v (only POST is allowed)", r.Method)
		s.sendErrorJSON(w, r, err)
		return
	}

	contentType := r.Header.Get("Content-Type")
	if i := strings.Index(contentType, ";"); i >= 0 {
		contentType = contentType[:i]
	}
	contentType = strings.TrimSpace(strings.ToLower(contentType))

	switch contentType {
	case "application/json":
		if s.OnRequest != nil {
			if err := s.OnRequest(w, r); err != nil {
				var rpcErr WebRPCError
				if !errors.As(err, &rpcErr) {
					rpcErr = ErrWebrpcEndpoint.WithCause(err)
				}
				s.sendErrorJSON(w, r, rpcErr)
				return
			}
		}

		s.serveRpcMethodJSON(ctx, w, r)
	default:
		err := ErrWebrpcBadRequest.WithCausef("unsupported Content-Type %q (only application/json is allowed)", r.Header.Get("Content-Type"))
		s.sendErrorJSON(w, r, err)
	}
}

func (s *testApiRestService) serveRpcMethodJSON(ctx context.Context, w http.ResponseWriter, r *http.Request) {
	ctx = context.WithValue(ctx, MethodNameCtxKey, "RpcMethod")

	reqBody, err := io.ReadAll(r.Body)
	if err != nil {
		s.sendErrorJSON(w, r, ErrWebrpcBadRequest.WithCausef("failed to read request data: %w", err))
		return
	}
	defer r.Body.Close()

	reqPayload := struct {
		Arg0 uint64 `json:"id"`
	}{}
	if err := jsonUnmarshal(reqBody, &reqPayload); err != nil {
		s.sendErrorJSON(w, r, ErrWebrpcBadRequest.WithCausef("failed to unmarshal request data: %w", err))
		return
	}

	// Call service method implementation.
	ret0, err := s.TestApiRestServer.RpcMethod(ctx, reqPayload.Arg0)
	if err != nil {
		var rpcErr WebRPCError
		if !errors.As(err, &rpcErr) {
			rpcErr = ErrWebrpcEndpoint.WithCause(err)
		}
		s.sendErrorJSON(w, r, rpcErr)
		return
	}

	respPayload := struct {
		Ret0 *Item `json:"item"`
	}{ret0}
	respBody, err := json.Marshal(respPayload)
	if err != nil {
		s.sendErrorJSON(w, r, ErrWebrpcBadResponse.WithCausef("failed to marshal json response: %w", err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write(respBody)
}

